INSERT INTO internal.pipeline_trigger_events (name) VALUES
  ('model.field.option.created'),
  ('model.field.option.updated'),
  ('model.rule.created'),
  ('model.rule.updated'),
  ('model.rule.removed'),
  ('model.link_rule.set'),
  ('model.link_rule.removed'),
  ('model.version.discarded'),
  ('sheet.definition.version.published'),
  ('sheet.definition.version.retired'),
  ('notebook.template.version.published'),
  ('notebook.template.version.retired'),
  ('record.alias.added'),
  ('record.alias.removed'),
  ('label.template.created'),
  ('label.template.updated')
INSERT INTO internal.pipeline_actions (operation, definition) VALUES
  ('create_model_record', '{"operation":"create_model_record","rpc":"create_model_record","label":"Create record","description":"Create an experiment, sample, material, report or supported model record in a project.","arguments":[{"name":"p_project_id","type":"uuid","required":true,"nullable":false},{"name":"p_kind","type":"text","required":true,"nullable":false},{"name":"p_title","type":"text","required":true,"nullable":false},{"name":"p_status","type":"text","required":false,"nullable":false},{"name":"p_tags","type":"text[]","required":false,"nullable":false},{"name":"p_properties","type":"jsonb","required":false,"nullable":false},{"name":"p_custom_fields","type":"jsonb","required":false,"nullable":false}]}'::jsonb),
  ('start_experiment', '{"operation":"start_experiment","rpc":"start_experiment","label":"Start an experiment","description":"Moves a planned experiment to running, optionally on a protocol version. The protocol must be one the project may use.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"bigint","required":true,"nullable":false},{"name":"p_protocol_version_id","type":"uuid","required":false,"nullable":true},{"name":"p_reason","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('set_experiment_status', '{"operation":"set_experiment_status","rpc":"set_experiment_status","label":"Change an experiment’s status","description":"Moves an experiment to another status, such as on hold or complete. Some moves need a reason when the workspace asks for one.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"bigint","required":true,"nullable":false},{"name":"p_status","type":"text","required":true,"nullable":false},{"name":"p_reason","type":"text","required":true,"nullable":true}]}'::jsonb),
  ('delete_experiment_draft', '{"operation":"delete_experiment_draft","rpc":"delete_experiment_draft","label":"Delete a draft experiment","description":"Deletes a draft experiment that was never submitted. Only its author, or a workspace admin, may.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false}]}'::jsonb),
  ('set_experiment_decision', '{"operation":"set_experiment_decision","rpc":"set_experiment_decision","label":"Record what an experiment showed","description":"Records the outcome against the hypothesis: `supported`, `refuted` or `inconclusive`, with notes. Leave the decision out to clear it.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_decision","type":"text","required":true,"nullable":true},{"name":"p_notes","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('create_plan_from_project', '{"operation":"create_plan_from_project","rpc":"create_plan_from_project","label":"Plan a project from another","description":"Copies the planned experiments and tasks of one project into another, starting on a date, with their gaps kept.","arguments":[{"name":"p_target_project_id","type":"uuid","required":true,"nullable":false},{"name":"p_source_project_id","type":"uuid","required":true,"nullable":false},{"name":"p_start_date","type":"date","required":true,"nullable":false}]}'::jsonb),
  ('add_record_alias', '{"operation":"add_record_alias","rpc":"add_record_alias","label":"Add another name to a record","description":"Gives a record another name it can be found by, such as a supplier code or an old identifier. Returns the alias.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_alias","type":"text","required":true,"nullable":false}]}'::jsonb),
  ('remove_record_alias', '{"operation":"remove_record_alias","rpc":"remove_record_alias","label":"Remove another name from a record","description":"Takes one of a record’s other names off it.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_alias","type":"text","required":true,"nullable":false}]}'::jsonb),
  ('save_trail_evidence', '{"operation":"save_trail_evidence","rpc":"save_trail_evidence","label":"Save a trail of steps on a record","description":"Saves the steps that led to a result, such as the records and datasets followed, as evidence on the record. Saved trails cannot be changed.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_steps","type":"jsonb","required":true,"nullable":false},{"name":"p_note","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('record_qc_check', '{"operation":"record_qc_check","rpc":"record_qc_check","label":"Record a QC check on a run","description":"Adds a quality check result to an instrument run: its name, `info`, `pass`, `warn` or `fail`, a message and any detail.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_run_id","type":"uuid","required":true,"nullable":true},{"name":"p_check_name","type":"text","required":true,"nullable":false},{"name":"p_check_type","type":"text","required":false,"nullable":false},{"name":"p_message","type":"text","required":false,"nullable":true},{"name":"p_detail","type":"jsonb","required":false,"nullable":false}]}'::jsonb),
  ('set_label_template_archived', '{"operation":"set_label_template_archived","rpc":"set_label_template_archived","label":"Archive or restore a label template","description":"Stops a label template being offered when printing, or brings it back.","arguments":[{"name":"p_template_id","type":"uuid","required":true,"nullable":false},{"name":"p_archived","type":"boolean","required":true,"nullable":false}]}'::jsonb),
  ('create_workspace_model', '{"operation":"create_workspace_model","rpc":"create_workspace_model","label":"Add a record type","description":"Adds a record type (model) to the workspace, such as Cell line or Supplier, with the prefix its identifiers start with. It starts with a draft version to add fields to. Returns the type.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_key","type":"text","required":true,"nullable":false},{"name":"p_name","type":"text","required":true,"nullable":false},{"name":"p_identifier_prefix","type":"text","required":true,"nullable":false},{"name":"p_description","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('create_model_subtype', '{"operation":"create_model_subtype","rpc":"create_model_subtype","label":"Add a kind of a record type","description":"Adds a record type that is a kind of another, such as Antibody under Reagent. It has the parent’s fields and can add its own. Returns the new type.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_parent_key","type":"text","required":true,"nullable":false},{"name":"p_key","type":"text","required":true,"nullable":false},{"name":"p_name","type":"text","required":true,"nullable":false},{"name":"p_identifier_prefix","type":"text","required":true,"nullable":false},{"name":"p_description","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('reparent_record_model', '{"operation":"reparent_record_model","rpc":"reparent_record_model","label":"Move a record type under another","description":"Makes a record type a kind of another one, or a top-level type again when `p_parent_key` is null. Returns the type.","arguments":[{"name":"p_model_id","type":"uuid","required":true,"nullable":false},{"name":"p_parent_key","type":"text","required":true,"nullable":true}]}'::jsonb),
  ('create_registry_model', '{"operation":"create_registry_model","rpc":"create_registry_model","label":"Add a registry","description":"Adds a record type that works as a registry (cell lines, constructs): entries get a running number and likely duplicates are refused by the key fields. `p_fields` is a JSON list of `{ name, label, type, required, options }`. Returns the type.","arguments":[{"name":"p_key","type":"text","required":true,"nullable":false},{"name":"p_name","type":"text","required":true,"nullable":false},{"name":"p_prefix","type":"text","required":true,"nullable":false},{"name":"p_description","type":"text","required":true,"nullable":true},{"name":"p_fields","type":"jsonb","required":true,"nullable":false},{"name":"p_key_fields","type":"text[]","required":true,"nullable":false},{"name":"p_sequence_field","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('create_request_model', '{"operation":"create_request_model","rpc":"create_request_model","label":"Add a request form","description":"Adds a record type that people send as a request (a sequencing request, a stores order), with an intro shown on the form. `p_fields` is a JSON list of `{ name, label, type, required, options }`. Returns the type.","arguments":[{"name":"p_key","type":"text","required":true,"nullable":false},{"name":"p_name","type":"text","required":true,"nullable":false},{"name":"p_prefix","type":"text","required":true,"nullable":false},{"name":"p_description","type":"text","required":true,"nullable":true},{"name":"p_fields","type":"jsonb","required":true,"nullable":false},{"name":"p_intro","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('create_starter_model', '{"operation":"create_starter_model","rpc":"create_starter_model","label":"Add a record type from a starter","description":"Adds a record type with its fields in one go, optionally used as an incident log. `p_fields` is a JSON list of `{ name, label, type, required, options }`. Returns the type.","arguments":[{"name":"p_key","type":"text","required":true,"nullable":false},{"name":"p_name","type":"text","required":true,"nullable":false},{"name":"p_prefix","type":"text","required":true,"nullable":false},{"name":"p_description","type":"text","required":true,"nullable":true},{"name":"p_fields","type":"jsonb","required":true,"nullable":false},{"name":"p_incident_log","type":"boolean","required":false,"nullable":false}]}'::jsonb),
  ('set_model_registry', '{"operation":"set_model_registry","rpc":"set_model_registry","label":"Make a record type a registry","description":"Turns a record type into a registry (or back), with the fields that say two entries are the same thing and the field that holds the running number. Returns the type.","arguments":[{"name":"p_model_key","type":"text","required":true,"nullable":false},{"name":"p_is_registry","type":"boolean","required":true,"nullable":false},{"name":"p_key_fields","type":"text[]","required":false,"nullable":false},{"name":"p_sequence_field","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('set_registry_lot_kind', '{"operation":"set_registry_lot_kind","rpc":"set_registry_lot_kind","label":"Choose a registry’s lot type","description":"Says which record type the lots of a registry entry are, such as Compound lot. Null takes it off. Returns the registry’s type.","arguments":[{"name":"p_model_key","type":"text","required":true,"nullable":false},{"name":"p_lot_kind","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('set_registry_sameness_rule', '{"operation":"set_registry_sameness_rule","rpc":"set_registry_sameness_rule","label":"Choose a registry’s same-thing rule","description":"Picks the plugin rule that decides when two entries of a registry are the same thing. `p_plugin_item` is `plugin.<plugin>.<rule>`; null goes back to the key fields.","arguments":[{"name":"p_model_key","type":"text","required":true,"nullable":false},{"name":"p_plugin_item","type":"text","required":true,"nullable":true}]}'::jsonb),
  ('set_model_incident_log', '{"operation":"set_model_incident_log","rpc":"set_model_incident_log","label":"Use a record type as an incident log","description":"Turns incident log behaviour on or off for a record type: entries show in the incident list with their severity and follow-up. Returns whether it is on.","arguments":[{"name":"p_model_key","type":"text","required":true,"nullable":false},{"name":"p_enabled","type":"boolean","required":true,"nullable":false}]}'::jsonb),
  ('set_request_form', '{"operation":"set_request_form","rpc":"set_request_form","label":"Take requests on a record type","description":"Says whether people can send a record type as a request, the intro on the form, and who handles requests.","arguments":[{"name":"p_model_key","type":"text","required":true,"nullable":false},{"name":"p_accepts","type":"boolean","required":true,"nullable":false},{"name":"p_intro","type":"text","required":false,"nullable":true},{"name":"p_handler_user_ids","type":"text[]","required":false,"nullable":false}]}'::jsonb),
  ('create_model_field', '{"operation":"create_model_field","rpc":"create_model_field","label":"Add a draft field","description":"Adds a field to a record type as a draft. It does nothing on records until it is switched on (`activate_model_field`). `p_logical_type` is `text`, `integer`, `decimal`, `boolean`, `date`, `timestamp`, `category` or `reference`. Returns the field.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_model_key","type":"text","required":true,"nullable":false},{"name":"p_field_name","type":"text","required":true,"nullable":false},{"name":"p_label","type":"text","required":true,"nullable":false},{"name":"p_logical_type","type":"text","required":true,"nullable":false},{"name":"p_nullable","type":"boolean","required":false,"nullable":false},{"name":"p_default_value","type":"jsonb","required":false,"nullable":true},{"name":"p_validation","type":"jsonb","required":false,"nullable":false},{"name":"p_unit","type":"jsonb","required":false,"nullable":true},{"name":"p_description","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('create_and_activate_model_field', '{"operation":"create_and_activate_model_field","rpc":"create_and_activate_model_field","label":"Add a field and switch it on","description":"Adds a field and switches it on in one go, with the choices of a category field. `p_options` is a JSON list of `{ key, label }`. Returns the field.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_model_key","type":"text","required":true,"nullable":false},{"name":"p_field_name","type":"text","required":true,"nullable":false},{"name":"p_label","type":"text","required":true,"nullable":false},{"name":"p_logical_type","type":"text","required":true,"nullable":false},{"name":"p_nullable","type":"boolean","required":true,"nullable":false},{"name":"p_default_value","type":"jsonb","required":true,"nullable":true},{"name":"p_validation","type":"jsonb","required":true,"nullable":false},{"name":"p_options","type":"jsonb","required":false,"nullable":false},{"name":"p_unit","type":"jsonb","required":false,"nullable":true},{"name":"p_description","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('activate_model_field', '{"operation":"activate_model_field","rpc":"activate_model_field","label":"Switch a field on","description":"Switches a draft field on, so records of the type show and keep it. Returns the field.","arguments":[{"name":"p_definition_id","type":"uuid","required":true,"nullable":false}]}'::jsonb),
  ('update_model_field', '{"operation":"update_model_field","rpc":"update_model_field","label":"Change a field","description":"Changes a field’s label, description, order, section, unit or checks. `p_patch` holds only what changes, such as `{ \"label\": \"Passage\", \"show_in_list\": true }`. A change that would break existing values goes through `apply_model_field_evolution`. Returns the field.","arguments":[{"name":"p_definition_id","type":"uuid","required":true,"nullable":false},{"name":"p_patch","type":"jsonb","required":true,"nullable":false}]}'::jsonb),
  ('retire_model_field', '{"operation":"retire_model_field","rpc":"retire_model_field","label":"Retire a field","description":"Takes a field out of use. Values already kept on records stay; new records no longer show it. Returns the field.","arguments":[{"name":"p_definition_id","type":"uuid","required":true,"nullable":false}]}'::jsonb),
  ('configure_model_field_semantics', '{"operation":"configure_model_field_semantics","rpc":"configure_model_field_semantics","label":"Say what a draft field measures","description":"Sets what a draft field means: the quantity and unit it measures, one value or many, where a category’s choices come from, or which record type a reference points at. Returns the field.","arguments":[{"name":"p_definition_id","type":"uuid","required":true,"nullable":false},{"name":"p_quantity","type":"jsonb","required":false,"nullable":true},{"name":"p_cardinality","type":"text","required":false,"nullable":false},{"name":"p_category_source","type":"jsonb","required":false,"nullable":true},{"name":"p_relationship","type":"jsonb","required":false,"nullable":true}]}'::jsonb),
  ('apply_model_field_evolution', '{"operation":"apply_model_field_evolution","rpc":"apply_model_field_evolution","label":"Change a field in use","description":"Makes a change `preview_model_field_evolution` checked. A change that needs confirming is refused with `SB071` unless `p_confirm` is true; one that would lose data is refused with `SB072`.","arguments":[{"name":"p_definition_id","type":"uuid","required":true,"nullable":false},{"name":"p_action","type":"text","required":true,"nullable":false},{"name":"p_patch","type":"jsonb","required":false,"nullable":false},{"name":"p_confirm","type":"boolean","required":false,"nullable":false}]}'::jsonb),
  ('create_model_field_option', '{"operation":"create_model_field_option","rpc":"create_model_field_option","label":"Add a choice to a category field","description":"Adds a choice to a category field, such as `frozen` / Frozen to a Status field. Returns the option.","arguments":[{"name":"p_definition_id","type":"uuid","required":true,"nullable":false},{"name":"p_key","type":"text","required":true,"nullable":false},{"name":"p_label","type":"text","required":true,"nullable":false},{"name":"p_display_order","type":"integer","required":false,"nullable":false}]}'::jsonb),
  ('update_model_field_option', '{"operation":"update_model_field_option","rpc":"update_model_field_option","label":"Rename or move a choice","description":"Changes the label people see for a choice, or where it sits. What is stored does not change. Returns the option.","arguments":[{"name":"p_option_id","type":"uuid","required":true,"nullable":false},{"name":"p_label","type":"text","required":true,"nullable":false},{"name":"p_display_order","type":"integer","required":true,"nullable":false}]}'::jsonb),
  ('retire_model_field_option', '{"operation":"retire_model_field_option","rpc":"retire_model_field_option","label":"Retire a choice","description":"Stops a choice being offered. Records that already have it keep it. Returns the option.","arguments":[{"name":"p_option_id","type":"uuid","required":true,"nullable":false}]}'::jsonb),
  ('create_model_rule', '{"operation":"create_model_rule","rpc":"create_model_rule","label":"Add a rule to a record type","description":"Adds a check on records of a type, such as “Passage must be under 30”. `p_effect` is `warn` (shown, not enforced), `block` (refuses the save) or `flag_block_submit` (can be saved, cannot be submitted). Returns the rule.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_model_key","type":"text","required":true,"nullable":false},{"name":"p_name","type":"text","required":true,"nullable":false},{"name":"p_field_keys","type":"text[]","required":true,"nullable":false},{"name":"p_condition","type":"jsonb","required":true,"nullable":false},{"name":"p_effect","type":"text","required":true,"nullable":false},{"name":"p_message","type":"text","required":true,"nullable":false}]}'::jsonb),
  ('update_model_rule', '{"operation":"update_model_rule","rpc":"update_model_rule","label":"Change a rule","description":"Changes a rule’s name, fields, condition, effect or message. `p_patch` holds only what changes. Returns the rule.","arguments":[{"name":"p_rule_id","type":"uuid","required":true,"nullable":false},{"name":"p_patch","type":"jsonb","required":true,"nullable":false}]}'::jsonb),
  ('remove_model_rule', '{"operation":"remove_model_rule","rpc":"remove_model_rule","label":"Remove a rule","description":"Takes a rule off a record type.","arguments":[{"name":"p_rule_id","type":"uuid","required":true,"nullable":false}]}'::jsonb),
  ('configure_model_relationship_rule', '{"operation":"configure_model_relationship_rule","rpc":"configure_model_relationship_rule","label":"Set how record types link","description":"Says how many links of a kind a record must or may have to records of another type, such as “every Lot links to exactly one Compound” (`p_min_links` 1, `p_max_links` 1). Setting it again for the same pair changes it. Returns the rule.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_source_model_key","type":"text","required":true,"nullable":false},{"name":"p_link_type","type":"text","required":true,"nullable":false},{"name":"p_target_model_key","type":"text","required":true,"nullable":false},{"name":"p_min_links","type":"integer","required":false,"nullable":false},{"name":"p_max_links","type":"integer","required":false,"nullable":true},{"name":"p_label","type":"text","required":false,"nullable":true}]}'::jsonb),
  ('remove_model_relationship_rule', '{"operation":"remove_model_relationship_rule","rpc":"remove_model_relationship_rule","label":"Remove a link rule","description":"Takes off a rule for how records of two types link.","arguments":[{"name":"p_rule_id","type":"uuid","required":true,"nullable":false}]}'::jsonb),
  ('create_record_model_version', '{"operation":"create_record_model_version","rpc":"create_record_model_version","label":"Start a new version of a record type","description":"Starts a draft of the next version of a record type from the current one. Records stay on their version until it is published and they are moved onto it. Returns the version.","arguments":[{"name":"p_model_id","type":"uuid","required":true,"nullable":false},{"name":"p_reason","type":"text","required":true,"nullable":false}]}'::jsonb),
  ('replace_record_model_version_definition', '{"operation":"replace_record_model_version_definition","rpc":"replace_record_model_version_definition","label":"Change a draft version of a record type","description":"Replaces what a draft version holds (its fields, sections and layout) with `p_definition`. Returns the version.","arguments":[{"name":"p_version_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false},{"name":"p_definition","type":"jsonb","required":true,"nullable":false},{"name":"p_reason","type":"text","required":true,"nullable":false}]}'::jsonb),
  ('discard_record_model_version', '{"operation":"discard_record_model_version","rpc":"discard_record_model_version","label":"Throw away a draft version of a record type","description":"Deletes a draft version that was never published. A published version cannot be thrown away.","arguments":[{"name":"p_version_id","type":"uuid","required":true,"nullable":false}]}'::jsonb),
  ('publish_record_model_version', '{"operation":"publish_record_model_version","rpc":"publish_record_model_version","label":"Publish a version of a record type","description":"Makes a draft version the current one. New records use it; existing ones stay on their version until moved. Needs `schema:publish`. Returns the version.","arguments":[{"name":"p_version_id","type":"uuid","required":true,"nullable":false}]}'::jsonb),
  ('migrate_open_experiments_to_model_version', '{"operation":"migrate_open_experiments_to_model_version","rpc":"migrate_open_experiments_to_model_version","label":"Move open experiments onto a version","description":"Moves every experiment of the type that is not finished (draft, planned, in progress, on hold or in review) onto a published version. Signed records stay where they are. Needs `schema:publish`. Returns how many moved.","arguments":[{"name":"p_model_id","type":"uuid","required":true,"nullable":false},{"name":"p_version_id","type":"uuid","required":true,"nullable":false},{"name":"p_reason","type":"text","required":true,"nullable":false}]}'::jsonb),
  ('upgrade_record_model_record', '{"operation":"upgrade_record_model_record","rpc":"upgrade_record_model_record","label":"Move a record onto a newer version","description":"Moves one record onto a published version of its type. Returns the record.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_version_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_metadata_version","type":"bigint","required":true,"nullable":false},{"name":"p_reason","type":"text","required":true,"nullable":false}]}'::jsonb),
  ('set_model_type', '{"operation":"set_model_type","rpc":"set_model_type","label":"Change what type a record is","description":"Moves a record, project or instrument to another type of the same family, such as Reagent to Antibody, with the new type’s field values. `p_host` is `records`, `project` or `instrument`. A signed record keeps its type.","arguments":[{"name":"p_host","type":"text","required":true,"nullable":false},{"name":"p_id","type":"uuid","required":true,"nullable":false},{"name":"p_model_key","type":"text","required":true,"nullable":false},{"name":"p_custom_fields","type":"jsonb","required":true,"nullable":false}]}'::jsonb),
  ('set_experiment_fields', '{"operation":"set_experiment_fields","rpc":"set_experiment_fields","label":"Set an experiment’s reviewer and end date","description":"Sets who reviews an experiment and when it is planned to end. Returns the record.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_reviewer_user_id","type":"text","required":false,"nullable":true},{"name":"p_planned_end","type":"date","required":false,"nullable":true}]}'::jsonb),
  ('create_sheet_definition', '{"operation":"create_sheet_definition","rpc":"create_sheet_definition","label":"Add a sheet definition","description":"Adds a reusable sheet layout (columns, parameters, calculations) with its first draft version. Returns `{ definition, version }`.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_key","type":"text","required":true,"nullable":false},{"name":"p_name","type":"text","required":true,"nullable":false},{"name":"p_description","type":"text","required":true,"nullable":true},{"name":"p_configuration","type":"jsonb","required":true,"nullable":false}]}'::jsonb),
  ('update_sheet_definition', '{"operation":"update_sheet_definition","rpc":"update_sheet_definition","label":"Rename a sheet definition","description":"Changes a sheet definition’s name or description. `p_patch` holds only what changes. Returns the definition.","arguments":[{"name":"p_definition_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false},{"name":"p_patch","type":"jsonb","required":true,"nullable":false}]}'::jsonb),
  ('create_sheet_definition_version', '{"operation":"create_sheet_definition_version","rpc":"create_sheet_definition_version","label":"Start a new version of a sheet definition","description":"Starts a draft of the next version of a sheet definition. Returns the version.","arguments":[{"name":"p_definition_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_definition_revision","type":"bigint","required":true,"nullable":false},{"name":"p_configuration","type":"jsonb","required":true,"nullable":false}]}'::jsonb),
  ('update_sheet_definition_draft', '{"operation":"update_sheet_definition_draft","rpc":"update_sheet_definition_draft","label":"Change a draft sheet definition","description":"Replaces the layout of a draft version. A published version cannot change. Returns the version.","arguments":[{"name":"p_version_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false},{"name":"p_configuration","type":"jsonb","required":true,"nullable":false}]}'::jsonb),
  ('publish_sheet_definition_version', '{"operation":"publish_sheet_definition_version","rpc":"publish_sheet_definition_version","label":"Publish a sheet definition","description":"Makes a draft version available for new sheets and templates. Needs `schema:publish`. Returns the version.","arguments":[{"name":"p_version_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false}]}'::jsonb),
  ('retire_sheet_definition_version', '{"operation":"retire_sheet_definition_version","rpc":"retire_sheet_definition_version","label":"Retire a version of a sheet definition","description":"Stops a published version being offered for new sheets. Sheets made from it keep working. Returns the version.","arguments":[{"name":"p_version_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false}]}'::jsonb),
  ('retire_sheet_definition', '{"operation":"retire_sheet_definition","rpc":"retire_sheet_definition","label":"Retire a sheet definition","description":"Stops a sheet definition being offered. Sheets made from it keep working, and it can be restored. Returns the definition.","arguments":[{"name":"p_definition_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false}]}'::jsonb),
  ('restore_sheet_definition', '{"operation":"restore_sheet_definition","rpc":"restore_sheet_definition","label":"Restore a sheet definition","description":"Offers a retired sheet definition again. Returns the definition.","arguments":[{"name":"p_definition_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false}]}'::jsonb),
  ('extract_sheet_definition_draft', '{"operation":"extract_sheet_definition_draft","rpc":"extract_sheet_definition_draft","label":"Turn a sheet into a definition","description":"Makes a new sheet definition, as a draft, from the chosen columns of a sheet. Returns `{ definition, version }`.","arguments":[{"name":"p_instance_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_instance_revision","type":"bigint","required":true,"nullable":false},{"name":"p_key","type":"text","required":true,"nullable":false},{"name":"p_name","type":"text","required":true,"nullable":false},{"name":"p_description","type":"text","required":true,"nullable":true},{"name":"p_selection","type":"jsonb","required":true,"nullable":false}]}'::jsonb),
  ('promote_local_field', '{"operation":"promote_local_field","rpc":"promote_local_field","label":"Make a sheet column a shared field","description":"Makes a column that only one sheet has into a field of a record type or a dataset schema, and points the sheet at it. Send the same `p_idempotency_key` to retry safely. Returns what changed.","arguments":[{"name":"p_instance_id","type":"uuid","required":true,"nullable":false},{"name":"p_field_id","type":"uuid","required":true,"nullable":false},{"name":"p_target","type":"text","required":true,"nullable":false},{"name":"p_schema_definition_id","type":"uuid","required":true,"nullable":true},{"name":"p_idempotency_key","type":"text","required":true,"nullable":false},{"name":"p_model_key","type":"text","required":false,"nullable":true},{"name":"p_schema_version_id","type":"uuid","required":false,"nullable":true},{"name":"p_expected_revision","type":"bigint","required":false,"nullable":true}]}'::jsonb),
  ('rename_sheet_instance', '{"operation":"rename_sheet_instance","rpc":"rename_sheet_instance","label":"Rename a sheet","description":"Gives a sheet a new name. Returns the sheet.","arguments":[{"name":"p_instance_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false},{"name":"p_name","type":"text","required":true,"nullable":false}]}'::jsonb),
  ('insert_sheet_block', '{"operation":"insert_sheet_block","rpc":"insert_sheet_block","label":"Add a measurement table to a notebook","description":"Adds a table block for a dataset schema to a notebook, after a block or at the end. Returns the block.","arguments":[{"name":"p_record_id","type":"uuid","required":true,"nullable":false},{"name":"p_after_block_id","type":"uuid","required":false,"nullable":true},{"name":"p_expected_structure_version","type":"integer","required":false,"nullable":true},{"name":"p_dataset_schema_id","type":"uuid","required":false,"nullable":true}]}'::jsonb),
  ('create_notebook_template', '{"operation":"create_notebook_template","rpc":"create_notebook_template","label":"Add a notebook template","description":"Adds a notebook template with its first draft version. Returns `{ template, version }`.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_key","type":"text","required":true,"nullable":false},{"name":"p_name","type":"text","required":true,"nullable":false},{"name":"p_description","type":"text","required":true,"nullable":true},{"name":"p_configuration","type":"jsonb","required":true,"nullable":false}]}'::jsonb),
  ('create_notebook_template_version', '{"operation":"create_notebook_template_version","rpc":"create_notebook_template_version","label":"Start a new version of a template","description":"Starts a draft of the next version of a notebook template. Returns the version.","arguments":[{"name":"p_template_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_template_revision","type":"bigint","required":true,"nullable":false},{"name":"p_configuration","type":"jsonb","required":true,"nullable":false}]}'::jsonb),
  ('update_notebook_template_version', '{"operation":"update_notebook_template_version","rpc":"update_notebook_template_version","label":"Change a draft template","description":"Replaces what a draft version holds. A published version cannot change. Returns the version.","arguments":[{"name":"p_version_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false},{"name":"p_configuration","type":"jsonb","required":true,"nullable":false}]}'::jsonb),
  ('retarget_notebook_template_sheet_placement', '{"operation":"retarget_notebook_template_sheet_placement","rpc":"retarget_notebook_template_sheet_placement","label":"Point a template’s sheet at another version","description":"Changes which sheet definition version a sheet in a draft template is made from. Returns the template version.","arguments":[{"name":"p_version_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false},{"name":"p_placement_id","type":"uuid","required":true,"nullable":false},{"name":"p_target_definition_version_id","type":"uuid","required":true,"nullable":false}]}'::jsonb),
  ('publish_notebook_template_version', '{"operation":"publish_notebook_template_version","rpc":"publish_notebook_template_version","label":"Publish a template","description":"Makes a draft version the one new notebooks are made from. Needs `schema:publish`. Returns the version.","arguments":[{"name":"p_version_id","type":"uuid","required":true,"nullable":false},{"name":"p_expected_revision","type":"bigint","required":true,"nullable":false},{"name":"p_reason","type":"text","required":true,"nullable":false}]}'::jsonb)
